* { margin: 0px; box-sizing: border-box; font-family: -apple-system, "Segoe UI", Roboto, sans-serif; }body { background: rgb(14, 11, 30); color: rgb(238, 233, 255); min-height: 100vh; }header { display: flex; justify-content: space-between; align-items: center; padding: 18px 40px; border-bottom: 1px solid rgb(42, 36, 71); }.logo { font-size: 22px; font-weight: 800; color: rgb(167, 139, 250); letter-spacing: -0.5px; }nav a { color: rgb(184, 179, 209); text-decoration: none; margin-left: 22px; font-size: 14px; }main { max-width: 640px; margin: 48px auto; padding: 0px 24px; }h1 { font-size: 30px; margin-bottom: 12px; }p { color: rgb(184, 179, 209); line-height: 1.6; margin-bottom: 16px; }.card { background: rgb(23, 19, 49); border: 1px solid rgb(42, 36, 71); border-radius: 14px; padding: 28px; margin-bottom: 20px; }.btn { display: inline-block; border: 0px; border-radius: 10px; padding: 14px 26px; font-size: 16px; font-weight: 700; cursor: pointer; text-decoration: none; }.btn-primary { background: rgb(124, 58, 237); color: rgb(255, 255, 255); }.btn-gold { background: linear-gradient(90deg, rgb(245, 158, 11), rgb(239, 68, 68)); color: rgb(255, 255, 255); font-size: 18px; padding: 18px 34px; }.btn-ghost { background: transparent; color: rgb(107, 101, 144); font-size: 12px; text-decoration: underline; padding: 6px; }.tiny { font-size: 11px; color: rgb(77, 72, 112); }footer { max-width: 640px; margin: 60px auto 40px; padding: 0px 24px; color: rgb(77, 72, 112); font-size: 11px; }footer a { color: rgb(77, 72, 112); }.spinner { width: 36px; height: 36px; border-width: 4px; border-style: solid; border-color: rgb(167, 139, 250) rgb(42, 36, 71) rgb(42, 36, 71); border-image: none; border-radius: 50%; animation: 1s linear 0s infinite normal none running spin; margin: 20px 0px; }@keyframes spin { 
  100% { transform: rotate(360deg); }
}label { display: block; padding: 10px 0px; color: rgb(214, 209, 238); cursor: pointer; }.countdown { color: rgb(245, 158, 11); font-weight: 800; }

